import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { OrbEngine } from "./OrbEngine";

// ── Recording fake CanvasRenderingContext2D ──────────────────────────────
// Records every call so tests can assert on draw behaviour without a real
// canvas backend (jsdom has none).
function makeFakeCtx() {
  const calls: { arc: number; fill: number; clearRect: number; setTransform: number } = {
    arc: 0,
    fill: 0,
    clearRect: 0,
    setTransform: 0,
  };
  const alphaLog: number[] = [];
  const fillStyleLog: string[] = [];
  let fillStyleValue = "";
  const ctx = {
    globalAlpha: 1,
    get fillStyle(): string {
      return fillStyleValue;
    },
    set fillStyle(value: string) {
      fillStyleValue = value;
    },
    clearRect: vi.fn(() => {
      calls.clearRect++;
    }),
    beginPath: vi.fn(),
    arc: vi.fn(() => {
      calls.arc++;
    }),
    fill: vi.fn(() => {
      calls.fill++;
      alphaLog.push(ctx.globalAlpha);
      fillStyleLog.push(ctx.fillStyle);
    }),
    setTransform: vi.fn(() => {
      calls.setTransform++;
    }),
  };
  return {
    ctx: ctx as unknown as CanvasRenderingContext2D,
    raw: ctx,
    calls,
    alphaLog,
    fillStyleLog,
  };
}

// ── Fake matchMedia: tracks per-query listeners so tests can dispatch
// synthetic "change" events (jsdom's real matchMedia never matches and the
// suite-wide stub in tests/setup.ts has no-op add/removeEventListener). ──
interface FakeMql {
  matches: boolean;
  listeners: Set<(e: { matches: boolean }) => void>;
}
function makeMatchMediaStub() {
  const byQuery = new Map<string, FakeMql>();
  const removeSpies: Array<{ query: string; spy: ReturnType<typeof vi.fn> }> = [];
  const matchMedia = vi.fn((query: string) => {
    let state = byQuery.get(query);
    if (!state) {
      state = { matches: false, listeners: new Set() };
      byQuery.set(query, state);
    }
    const removeEventListener = vi.fn(
      (_type: string, cb: (e: { matches: boolean }) => void) => {
        state!.listeners.delete(cb);
      },
    );
    removeSpies.push({ query, spy: removeEventListener });
    return {
      get matches() {
        return state!.matches;
      },
      media: query,
      addEventListener: vi.fn((_type: string, cb: (e: { matches: boolean }) => void) => {
        state!.listeners.add(cb);
      }),
      removeEventListener,
      dispatchEvent: () => false,
    };
  });
  return {
    matchMedia,
    trigger(query: string, matches: boolean) {
      const state = byQuery.get(query);
      if (!state) return;
      state.matches = matches;
      for (const cb of state.listeners) cb({ matches });
    },
    listenerCount(query: string) {
      return byQuery.get(query)?.listeners.size ?? 0;
    },
    removeCallCount(query: string) {
      return removeSpies
        .filter((r) => r.query === query)
        .reduce((n, r) => n + r.spy.mock.calls.length, 0);
    },
  };
}

// ── Fake IntersectionObserver ────────────────────────────────────────────
function makeIOStub() {
  let callback: IntersectionObserverCallback | null = null;
  const disconnect = vi.fn();
  const observe = vi.fn();
  class FakeIntersectionObserver {
    constructor(cb: IntersectionObserverCallback) {
      callback = cb;
    }
    observe(el: Element): void {
      observe(el);
    }
    unobserve(): void {}
    disconnect(): void {
      disconnect();
    }
    takeRecords(): IntersectionObserverEntry[] {
      return [];
    }
  }
  return {
    FakeIntersectionObserver,
    disconnect,
    observe,
    trigger(isIntersecting: boolean) {
      callback?.(
        [{ isIntersecting } as IntersectionObserverEntry],
        null as unknown as IntersectionObserver,
      );
    },
  };
}

function setHidden(hidden: boolean): void {
  Object.defineProperty(document, "hidden", {
    configurable: true,
    value: hidden,
  });
}

let mm: ReturnType<typeof makeMatchMediaStub>;
let io: ReturnType<typeof makeIOStub>;
let rafSpy: ReturnType<typeof vi.spyOn>;
let cafSpy: ReturnType<typeof vi.spyOn>;
let rafCallbacks: Array<FrameRequestCallback>;
let nextRafId: number;

function flushRaf(time = 16): void {
  const cbs = rafCallbacks.splice(0, rafCallbacks.length);
  for (const cb of cbs) cb(time);
}

beforeEach(() => {
  mm = makeMatchMediaStub();
  io = makeIOStub();
  vi.stubGlobal("matchMedia", mm.matchMedia);
  vi.stubGlobal("IntersectionObserver", io.FakeIntersectionObserver);
  setHidden(false);

  rafCallbacks = [];
  nextRafId = 1;
  rafSpy = vi.spyOn(window, "requestAnimationFrame").mockImplementation((cb) => {
    rafCallbacks.push(cb);
    return nextRafId++;
  });
  cafSpy = vi.spyOn(window, "cancelAnimationFrame").mockImplementation(() => {});
});

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
  setHidden(false);
});

function makeEngine(params?: Partial<{ mode: "orbits" | "scan"; size: number; speed: number }>) {
  const canvas = document.createElement("canvas");
  const { ctx, raw, calls, alphaLog, fillStyleLog } = makeFakeCtx();
  const engine = new OrbEngine(canvas, ctx, {
    mode: params?.mode ?? "orbits",
    size: params?.size ?? 96,
    speed: params?.speed ?? 1,
  });
  return { canvas, ctx: raw, calls, alphaLog, fillStyleLog, engine };
}

const REAL_COG_AI_GRADIENT =
  "linear-gradient(135deg, rgb(26, 79, 214) 0%, rgb(109, 40, 217) 50%, rgb(180, 83, 9) 100%)";

/**
 * Stubs `getComputedStyle` so a probe element carrying the `bg-cog-ai`
 * class resolves to the real design-token gradient string — jsdom itself
 * never computes gradient backgrounds, so this is the only way to exercise
 * the multi-stop sampling path in tests. Every other element (the canvas,
 * `<html>`, …) falls through to the real jsdom implementation.
 */
function stubGradientProbe() {
  const real = window.getComputedStyle.bind(window);
  return vi.spyOn(window, "getComputedStyle").mockImplementation((el, ...rest) => {
    if (el instanceof HTMLElement && el.classList.contains("bg-cog-ai")) {
      return { backgroundImage: REAL_COG_AI_GRADIENT } as CSSStyleDeclaration;
    }
    return real(el, ...rest);
  });
}

describe("OrbEngine — draw()", () => {
  it("clears the canvas, sets fillStyle, and draws an arc+fill per particle", () => {
    const { ctx, engine } = makeEngine();
    engine.draw(1.2);
    expect(ctx.clearRect).toHaveBeenCalled();
    expect(typeof ctx.fillStyle).toBe("string");
    expect(ctx.arc).toHaveBeenCalled();
    expect(ctx.fill).toHaveBeenCalled();
    expect(ctx.arc.mock.calls.length).toBe(ctx.fill.mock.calls.length);
  });

  it("resets globalAlpha to 1 after drawing", () => {
    const { ctx, engine } = makeEngine();
    engine.draw(1.2);
    expect(ctx.globalAlpha).toBe(1);
  });

  it("resolves colour once and reuses it across repeated draw() calls (no per-frame layout read)", () => {
    const { engine, canvas } = makeEngine();
    const spy = vi.spyOn(window, "getComputedStyle");
    engine.draw(0);
    const afterFirst = spy.mock.calls.filter((c) => c[0] === canvas).length;
    engine.draw(1);
    engine.draw(2);
    engine.draw(3);
    const afterMany = spy.mock.calls.filter((c) => c[0] === canvas).length;
    expect(afterFirst).toBe(1);
    expect(afterMany).toBe(1);
  });
});

describe("OrbEngine — applySize()", () => {
  it("sets backing store to size * dpr and CSS px size, and calls setTransform", () => {
    const { canvas, ctx, engine } = makeEngine({ size: 100 });
    engine.applySize();
    expect(canvas.width).toBe(100);
    expect(canvas.height).toBe(100);
    expect(canvas.style.width).toBe("100px");
    expect(canvas.style.height).toBe("100px");
    expect(ctx.setTransform).toHaveBeenCalledWith(1, 0, 0, 1, 0, 0);
  });

  it("does not re-run when size is unchanged (setParams with same size)", () => {
    const { ctx, engine } = makeEngine({ size: 100 });
    engine.applySize();
    expect(ctx.setTransform.mock.calls.length).toBe(1);
    engine.setParams({ mode: "orbits", size: 100, speed: 2 });
    expect(ctx.setTransform.mock.calls.length).toBe(1);
  });

  it("re-runs when size changes", () => {
    const { ctx, engine } = makeEngine({ size: 100 });
    engine.applySize();
    engine.setParams({ mode: "orbits", size: 150, speed: 1 });
    expect(ctx.setTransform.mock.calls.length).toBe(2);
  });

  it("re-runs when devicePixelRatio changes even though size is unchanged", () => {
    const original = Object.getOwnPropertyDescriptor(window, "devicePixelRatio");
    Object.defineProperty(window, "devicePixelRatio", { configurable: true, value: 1 });
    try {
      const { canvas, ctx, engine } = makeEngine({ size: 100 });
      engine.applySize();
      expect(ctx.setTransform.mock.calls.length).toBe(1);
      expect(canvas.width).toBe(100);

      Object.defineProperty(window, "devicePixelRatio", { configurable: true, value: 2 });
      engine.applySize();
      expect(ctx.setTransform.mock.calls.length).toBe(2);
      expect(canvas.width).toBe(200);
    } finally {
      if (original) {
        Object.defineProperty(window, "devicePixelRatio", original);
      } else {
        delete (window as { devicePixelRatio?: number }).devicePixelRatio;
      }
    }
  });
});

describe("OrbEngine — start()/stop() idempotency", () => {
  it("start() twice schedules exactly one rAF", () => {
    const { engine } = makeEngine();
    engine.start();
    engine.start();
    expect(rafSpy).toHaveBeenCalledTimes(1);
  });

  it("stop() twice cancels exactly once", () => {
    const { engine } = makeEngine();
    engine.start();
    engine.stop();
    engine.stop();
    expect(cafSpy).toHaveBeenCalledTimes(1);
  });

  it("adjusts the time base so resuming does not jump the animation", () => {
    const { ctx, engine } = makeEngine();
    engine.start();
    flushRaf(0);
    flushRaf(1000); // t ~ 1s in
    engine.stop();
    // Simulate real elapsed pause time, then resume.
    engine.start();
    flushRaf(5000);
    // No assertion on exact t value beyond "it drew again without throwing";
    // the key behavioural guarantee is covered by the paused-duration offset
    // math not producing a discontinuity large enough to break rendering.
    expect(ctx.arc).toHaveBeenCalled();
  });
});

describe("OrbEngine — mount(): reduced motion", () => {
  it("never calls requestAnimationFrame and draws exactly one static frame at t = 0.6", () => {
    mm.trigger("(prefers-reduced-motion: reduce)", false); // no-op pre-mount
    vi.stubGlobal(
      "matchMedia",
      vi.fn((q: string) => (q.includes("reduced-motion") ? { matches: true, addEventListener: vi.fn(), removeEventListener: vi.fn() } : mm.matchMedia(q))),
    );
    const { engine, ctx } = makeEngine();
    engine.mount();
    expect(rafSpy).not.toHaveBeenCalled();
    expect(ctx.arc).toHaveBeenCalled();
  });

  it("picks up a later switch back to normal motion and starts the loop", () => {
    let current = true;
    // A plain outer `let` reassigned only from inside a nested callback is
    // narrowed by TS control-flow analysis to its literal initializer (`null`)
    // at every read reachable via the linear flow graph — the closure
    // assignment isn't visible from there, so an optional call on it resolves
    // the non-nullish branch to `never`. Route the listener through a holder
    // object instead; property reads aren't narrowed that way.
    const holder: { cb: ((e: { matches: boolean }) => void) | null } = { cb: null };
    const removeEventListener = vi.fn();
    const reducedMql = {
      get matches() {
        return current;
      },
      addEventListener: vi.fn((_type: string, cb: (e: { matches: boolean }) => void) => {
        holder.cb = cb;
      }),
      removeEventListener,
    };
    vi.stubGlobal(
      "matchMedia",
      vi.fn((q: string) => (q.includes("reduced-motion") ? reducedMql : mm.matchMedia(q))),
    );

    const { engine } = makeEngine();
    engine.mount();
    expect(rafSpy).not.toHaveBeenCalled();

    current = false;
    holder.cb?.({ matches: false });
    expect(rafSpy).toHaveBeenCalled();

    engine.destroy();
    expect(removeEventListener).toHaveBeenCalledTimes(1);
  });
});

describe("OrbEngine — mount(): reduced-motion still installs visibility gating", () => {
  it("installs the IntersectionObserver and observes the canvas even under reduced motion", () => {
    mm.trigger("(prefers-reduced-motion: reduce)", false); // no-op pre-mount
    vi.stubGlobal(
      "matchMedia",
      vi.fn((q: string) => (q.includes("reduced-motion") ? { matches: true, addEventListener: vi.fn(), removeEventListener: vi.fn() } : mm.matchMedia(q))),
    );
    const { engine } = makeEngine();
    engine.mount();
    expect(io.observe).toHaveBeenCalled();
  });

  it("keeps the visibilitychange listener active so a loop later resumed via reduced-motion-off can still be paused by a hidden tab", () => {
    let current = true;
    const holder: { cb: ((e: { matches: boolean }) => void) | null } = { cb: null };
    const reducedMql = {
      get matches() {
        return current;
      },
      addEventListener: vi.fn((_type: string, cb: (e: { matches: boolean }) => void) => {
        holder.cb = cb;
      }),
      removeEventListener: vi.fn(),
    };
    vi.stubGlobal(
      "matchMedia",
      vi.fn((q: string) => (q.includes("reduced-motion") ? reducedMql : mm.matchMedia(q))),
    );

    const { engine } = makeEngine();
    engine.mount();
    expect(rafSpy).not.toHaveBeenCalled();

    // Resume normal motion.
    current = false;
    holder.cb?.({ matches: false });
    expect(rafSpy).toHaveBeenCalled();

    // A background tab must still be able to stop the now-running loop —
    // this only works if visibilitychange was wired up during the
    // reduced-motion mount, not skipped by the early return.
    cafSpy.mockClear();
    setHidden(true);
    document.dispatchEvent(new Event("visibilitychange"));
    expect(cafSpy).toHaveBeenCalled();
  });
});

describe("OrbEngine — mount(): normal motion", () => {
  it("starts the loop after mount", () => {
    const { engine } = makeEngine();
    engine.mount();
    expect(rafSpy).toHaveBeenCalledTimes(1);
  });

  it("reduced-motion change stops the loop and repaints a static frame", () => {
    const { engine, ctx } = makeEngine();
    engine.mount();
    ctx.arc.mockClear();
    mm.trigger("(prefers-reduced-motion: reduce)", true);
    expect(cafSpy).toHaveBeenCalled();
    expect(ctx.arc).toHaveBeenCalled();
  });

  it("IO callback with isIntersecting: false stops the loop via cancelAnimationFrame", () => {
    const { engine } = makeEngine();
    engine.mount();
    io.trigger(false);
    expect(cafSpy).toHaveBeenCalled();
  });

  it("IO callback with isIntersecting: true (after false) resumes the loop", () => {
    const { engine } = makeEngine();
    engine.mount();
    io.trigger(false);
    rafSpy.mockClear();
    io.trigger(true);
    expect(rafSpy).toHaveBeenCalled();
  });

  it("visibilitychange to hidden pauses; back to visible resumes", () => {
    const { engine } = makeEngine();
    engine.mount();
    setHidden(true);
    document.dispatchEvent(new Event("visibilitychange"));
    expect(cafSpy).toHaveBeenCalled();

    rafSpy.mockClear();
    setHidden(false);
    document.dispatchEvent(new Event("visibilitychange"));
    expect(rafSpy).toHaveBeenCalled();
  });

  it("setPaused(true) stops the loop without clearing state; setPaused(false) resumes", () => {
    const { engine, ctx } = makeEngine();
    engine.mount();
    engine.setPaused(true);
    expect(cafSpy).toHaveBeenCalled();
    expect(ctx.clearRect).not.toHaveBeenCalled(); // stop() itself never draws/clears

    rafSpy.mockClear();
    engine.setPaused(false);
    expect(rafSpy).toHaveBeenCalled();
  });

  it("treats IntersectionObserver as visible when unavailable (feature-detect)", () => {
    vi.stubGlobal("IntersectionObserver", undefined);
    const { engine } = makeEngine();
    engine.mount();
    expect(rafSpy).toHaveBeenCalledTimes(1);
    expect(io.observe).not.toHaveBeenCalled();
  });
});

describe("OrbEngine — destroy()", () => {
  it("disconnects IntersectionObserver and MutationObserver, removes both mql listeners and visibilitychange, and draws nothing after", () => {
    const moDisconnect = vi.fn();
    class FakeMutationObserver {
      observe(): void {}
      disconnect(): void {
        moDisconnect();
      }
      takeRecords(): MutationRecord[] {
        return [];
      }
    }
    vi.stubGlobal("MutationObserver", FakeMutationObserver);

    const { engine, ctx } = makeEngine();
    engine.mount();

    engine.destroy();

    expect(cafSpy).toHaveBeenCalled();
    expect(io.disconnect).toHaveBeenCalledTimes(1);
    expect(moDisconnect).toHaveBeenCalledTimes(1);
    expect(mm.removeCallCount("(prefers-reduced-motion: reduce)")).toBeGreaterThanOrEqual(1);
    expect(mm.removeCallCount("(prefers-color-scheme: dark)")).toBeGreaterThanOrEqual(1);

    ctx.arc.mockClear();
    ctx.clearRect.mockClear();
    // Post-destroy: none of the watched triggers may cause a draw.
    io.trigger(false);
    document.dispatchEvent(new Event("visibilitychange"));
    mm.trigger("(prefers-reduced-motion: reduce)", true);
    expect(ctx.arc).not.toHaveBeenCalled();
    expect(ctx.clearRect).not.toHaveBeenCalled();
  });

  it("stop() is idempotent when called via destroy() after an explicit stop()", () => {
    const { engine } = makeEngine();
    engine.mount();
    engine.stop();
    cafSpy.mockClear();
    engine.destroy();
    expect(cafSpy).not.toHaveBeenCalled();
  });

  it("ignores a direct draw() call after destroy()", () => {
    const { engine, ctx } = makeEngine();
    engine.mount();
    engine.destroy();
    ctx.clearRect.mockClear();
    engine.draw(1);
    expect(ctx.clearRect).not.toHaveBeenCalled();
  });
});

describe("OrbEngine — theme watchers", () => {
  it("invalidates the cached colour on a prefers-color-scheme change", () => {
    const { engine } = makeEngine();
    const spy = vi.spyOn(window, "getComputedStyle");
    engine.mount();
    const afterMount = spy.mock.calls.length;
    mm.trigger("(prefers-color-scheme: dark)", true);
    // A colour-scheme change alone (not reduced motion) marks dirty but
    // doesn't force a repaint outside the loop; the next draw() picks it up.
    engine.draw(1);
    expect(spy.mock.calls.length).toBeGreaterThan(afterMount);
  });

  it("repaints immediately on a theme invalidation while the loop is stopped (paused), even without reduced motion", () => {
    const { engine, ctx } = makeEngine();
    engine.mount();
    engine.setPaused(true);
    ctx.arc.mockClear();
    mm.trigger("(prefers-color-scheme: dark)", true);
    // setPaused()'s contract is "holds the last frame" — a theme flip while
    // paused/backgrounded must not leave the stale palette on screen
    // indefinitely, since nothing else will repaint it until resumed.
    expect(ctx.arc).toHaveBeenCalled();
  });
});

describe("OrbEngine — resolveDarkMode() precedence", () => {
  it('an explicit data-theme="light" wins over an OS dark preference', () => {
    const spy = stubGradientProbe();
    const originalTheme = document.documentElement.getAttribute("data-theme");
    try {
      document.documentElement.removeAttribute("data-theme");
      const { engine: lightEngine, fillStyleLog: lightLog } = makeEngine();
      lightEngine.mount();
      lightEngine.draw(1.2);

      mm.trigger("(prefers-color-scheme: dark)", true);
      document.documentElement.setAttribute("data-theme", "light");
      const { engine: forcedLightEngine, fillStyleLog: forcedLog } = makeEngine();
      forcedLightEngine.mount();
      forcedLightEngine.draw(1.2);

      // Per styles/index.css, an explicit data-theme="light" beats the OS
      // media query — the engine must sample the LIGHT ramp window here,
      // not the dark one, matching the un-forced light draw exactly.
      expect(forcedLog).toEqual(lightLog);
    } finally {
      if (originalTheme === null) {
        document.documentElement.removeAttribute("data-theme");
      } else {
        document.documentElement.setAttribute("data-theme", originalTheme);
      }
      spy.mockRestore();
    }
  });
});

describe("OrbEngine — setParams()", () => {
  it("updates mode/size/speed and keeps the loop in sync", () => {
    const { engine } = makeEngine({ mode: "orbits" });
    engine.mount();
    rafSpy.mockClear();
    cafSpy.mockClear();
    engine.setParams({ mode: "scan", size: 96, speed: 2 });
    // Still should be running (all conditions favorable) — sync() re-affirms start(),
    // which is a no-op call into requestAnimationFrame guard (raf already set).
    expect(cafSpy).not.toHaveBeenCalled();
  });

  it("redraws the static frame under reduced motion after a size change, instead of leaving the resized (cleared) canvas blank", () => {
    mm.trigger("(prefers-reduced-motion: reduce)", false); // no-op pre-mount
    vi.stubGlobal(
      "matchMedia",
      vi.fn((q: string) => (q.includes("reduced-motion") ? { matches: true, addEventListener: vi.fn(), removeEventListener: vi.fn() } : mm.matchMedia(q))),
    );
    const { engine, ctx, canvas } = makeEngine({ size: 96 });
    engine.mount();
    ctx.arc.mockClear();
    engine.setParams({ mode: "orbits", size: 120, speed: 1 });
    expect(canvas.width).toBe(120);
    // The resize clears the backing store — under reduced motion nothing
    // else ever repaints it, so setParams must redraw the static frame.
    expect(ctx.arc).toHaveBeenCalled();
    expect(rafSpy).not.toHaveBeenCalled();
  });
});

describe("OrbEngine — gradient colour sampling", () => {
  it("samples different fillStyle values across particles when the cog-ai gradient resolves", () => {
    const spy = stubGradientProbe();
    const { engine, fillStyleLog } = makeEngine();
    engine.draw(1.2);
    const distinct = new Set(fillStyleLog);
    expect(distinct.size).toBeGreaterThanOrEqual(2);
    spy.mockRestore();
  });

  it("falls back to a single resolved colour under jsdom (no gradient support) and never throws", () => {
    const { engine, fillStyleLog } = makeEngine();
    expect(() => engine.draw(1.2)).not.toThrow();
    const distinct = new Set(fillStyleLog);
    expect(distinct.size).toBe(1);
    expect(fillStyleLog.length).toBeGreaterThan(0);
  });

  it("removes the probe element from document.body after resolving, in both the gradient and fallback paths", () => {
    const spy = stubGradientProbe();
    const before = document.body.children.length;
    const { engine } = makeEngine();
    engine.draw(1.2);
    expect(document.body.children.length).toBe(before);
    spy.mockRestore();

    const beforeFallback = document.body.children.length;
    const { engine: fallbackEngine } = makeEngine();
    fallbackEngine.draw(1.2);
    expect(document.body.children.length).toBe(beforeFallback);
  });

  it("resolves stops once across N frames — getComputedStyle call count does not grow with frames or particle count", () => {
    const spy = stubGradientProbe();
    const { engine } = makeEngine();
    engine.draw(0);
    const afterFirst = spy.mock.calls.length;
    engine.draw(1);
    engine.draw(2);
    engine.draw(3);
    const afterMany = spy.mock.calls.length;
    expect(afterMany).toBe(afterFirst);
    spy.mockRestore();
  });

  it("re-resolves after a theme invalidation (colour-scheme change) but not before", () => {
    const spy = stubGradientProbe();
    const { engine } = makeEngine();
    engine.mount();
    engine.draw(1);
    const afterFirstDraw = spy.mock.calls.length;
    engine.draw(1.5); // same invalidation window — no new resolution
    expect(spy.mock.calls.length).toBe(afterFirstDraw);

    mm.trigger("(prefers-color-scheme: dark)", true);
    engine.draw(2);
    expect(spy.mock.calls.length).toBeGreaterThan(afterFirstDraw);
    spy.mockRestore();
  });
});


