/**
 * Framework-free render engine for the wizard's "thinking orb" ambient
 * loader. Owns exactly one `<canvas>` + its 2D context and drives the pure
 * motion math in `./orbMath` once per frame. Deliberately has NO React
 * import — the next task wraps this in a thin `ThinkingOrb.tsx` shell that
 * owns the canvas ref, the null-context guard, and prop wiring; this class
 * owns everything else: DPR-aware sizing, the rAF loop, visibility/
 * reduced-motion/theme watching, and pause semantics.
 */

import {
  frameParticles,
  parseGradientStops,
  prefersReducedMotion,
  rampPosition,
  resolveDpr,
  sampleRamp,
  shouldRunLoop,
  type RampWindow,
  type Rgb,
  type ThinkingOrbMode,
} from "./orbMath";

export interface OrbEngineParams {
  readonly mode: ThinkingOrbMode;
  readonly size: number;
  readonly speed: number;
}

const STATIC_FRAME_T = 0.6;

// The AI gradient token (`bg-cog-ai`, tailwind.preset.ts) runs indigo →
// violet → amber. Particles sample a sub-window of that ramp rather than
// its full span:
//
// - `to: 0.8` keeps the pure-amber end stop out of reach entirely, so amber
//   only ever appears as a highlight tint on the nearest (highest-depth)
//   particles instead of becoming a third, equally-weighted color band.
// - `from` starts at the indigo end in light mode, but is pulled forward to
//   ~0.15 in dark mode: the ramp's darkest indigo (#1A4FD6) has too little
//   contrast against a dark surface, so dark mode skips past it toward the
//   brighter violet midtone before sampling begins.
const RAMP_WINDOW_LIGHT: RampWindow = { from: 0, to: 0.8 };
const RAMP_WINDOW_DARK: RampWindow = { from: 0.15, to: 0.8 };

export class OrbEngine {
  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D;

  private mode: ThinkingOrbMode;
  private size: number;
  private speed: number;

  private lastAppliedSize: number | null = null;
  private lastAppliedDpr: number | null = null;

  private paused = false;
  private visible = true;
  private documentHidden = false;
  private reducedMotion = false;

  private raf: number | null = null;
  private t0: number | null = null;
  private pausedAt: number | null = null;

  private dirty = true;
  private stops: readonly Rgb[] = [];
  private darkMode = false;

  private destroyed = false;

  private io: IntersectionObserver | null = null;
  private mutationObserver: MutationObserver | null = null;
  private reducedMotionMql: MediaQueryList | null = null;
  private colorSchemeMql: MediaQueryList | null = null;

  constructor(
    canvas: HTMLCanvasElement,
    ctx: CanvasRenderingContext2D,
    params: OrbEngineParams,
  ) {
    this.canvas = canvas;
    this.ctx = ctx;
    this.mode = params.mode;
    this.size = params.size;
    this.speed = params.speed;
  }

  /**
   * Resizes the backing store to `size * dpr`, sets the CSS box to `size`
   * px, and re-maps the drawing transform to CSS px. No-ops when neither
   * `size` nor the resolved `dpr` has actually changed — re-running
   * unconditionally reallocates the backing store on every parent
   * re-render and visibly flashes the orb. Caching only `size` would miss a
   * devicePixelRatio change (e.g. dragging the window to a different-DPI
   * display), leaving the backing store permanently under-resolved.
   */
  applySize(): void {
    const dpr = resolveDpr(window);
    if (this.lastAppliedSize === this.size && this.lastAppliedDpr === dpr) {
      return;
    }
    this.canvas.width = this.size * dpr;
    this.canvas.height = this.size * dpr;
    this.canvas.style.width = `${this.size}px`;
    this.canvas.style.height = `${this.size}px`;
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.lastAppliedSize = this.size;
    this.lastAppliedDpr = dpr;
  }

  /** Draws a single frame at time `t` (seconds). */
  draw(t: number): void {
    if (this.destroyed) {
      return;
    }
    const { ctx, size } = this;
    ctx.clearRect(0, 0, size, size);
    const stops = this.resolveStops();
    const rampWindow = this.darkMode ? RAMP_WINDOW_DARK : RAMP_WINDOW_LIGHT;
    const particles = frameParticles(this.mode, t, size, this.speed);
    for (const p of particles) {
      const color = sampleRamp(stops, rampPosition(p.d, rampWindow));
      ctx.fillStyle = `rgb(${color.r}, ${color.g}, ${color.b})`;
      ctx.globalAlpha = p.a;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /**
   * Reads reduced-motion, sizes the canvas, installs the theme watchers,
   * then either paints one static frame (reduced motion) or starts the
   * loop. The IntersectionObserver and `visibilitychange` listener are
   * installed unconditionally — not skipped under reduced motion — because
   * `onReducedMotionChange` can flip `reducedMotion` back to `false` later
   * and resume the loop via `sync()`; without visibility/IO gating already
   * wired up at that point, the resumed loop would run forever in a
   * background tab or while scrolled off-screen.
   */
  mount(): void {
    this.reducedMotion = prefersReducedMotion(window);
    this.applySize();
    this.installThemeWatchers();

    // Attached unconditionally (not just in the not-reduced branch below) so
    // an orb that mounts while the OS is already in reduced-motion mode still
    // picks up a later switch back to normal motion and starts the loop.
    this.reducedMotionMql = window.matchMedia("(prefers-reduced-motion: reduce)");
    this.reducedMotionMql.addEventListener("change", this.onReducedMotionChange);

    if (typeof IntersectionObserver === "undefined") {
      this.visible = true;
    } else {
      this.io = new IntersectionObserver((entries) => {
        const entry = entries[entries.length - 1];
        this.visible = entry ? entry.isIntersecting : true;
        this.sync();
      });
      this.io.observe(this.canvas);
    }

    this.documentHidden = document.hidden;
    document.addEventListener("visibilitychange", this.onVisibilityChange);

    if (this.reducedMotion) {
      this.draw(STATIC_FRAME_T);
      return;
    }

    this.sync();
  }

  /** Idempotent: a second call while already running is a no-op. */
  start(): void {
    if (this.raf !== null || this.destroyed) {
      return;
    }
    const now = performance.now();
    if (this.t0 === null) {
      this.t0 = now;
    } else if (this.pausedAt !== null) {
      this.t0 += now - this.pausedAt;
    }
    this.pausedAt = null;

    const loop = (time: number): void => {
      const t0 = this.t0 ?? time;
      this.draw((time - t0) / 1000);
      this.raf = window.requestAnimationFrame(loop);
    };
    this.raf = window.requestAnimationFrame(loop);
  }

  /** Idempotent: a second call while already stopped is a no-op. */
  stop(): void {
    if (this.raf === null) {
      return;
    }
    window.cancelAnimationFrame(this.raf);
    this.raf = null;
    this.pausedAt = performance.now();
  }

  /** Single source of truth: starts or stops the loop based on current state. */
  sync(): void {
    const shouldRun =
      !this.paused &&
      shouldRunLoop({
        visible: this.visible,
        documentHidden: this.documentHidden,
        reducedMotion: this.reducedMotion,
      });
    if (shouldRun) {
      this.start();
    } else {
      this.stop();
    }
  }

  setParams(params: OrbEngineParams): void {
    this.mode = params.mode;
    this.size = params.size;
    this.speed = params.speed;
    this.applySize();
    // applySize() reassigns canvas.width/height, which clears the backing
    // store. Under reduced motion the loop never runs to repaint it, so —
    // mirroring invalidate() — redraw the static frame here directly.
    if (this.reducedMotion) {
      this.draw(STATIC_FRAME_T);
    }
    this.sync();
  }

  /** Paused holds the last frame — it never clears the canvas or tears anything down. */
  setPaused(paused: boolean): void {
    this.paused = paused;
    this.sync();
  }

  destroy(): void {
    this.stop();
    this.io?.disconnect();
    this.io = null;
    this.mutationObserver?.disconnect();
    this.mutationObserver = null;
    this.reducedMotionMql?.removeEventListener("change", this.onReducedMotionChange);
    this.reducedMotionMql = null;
    this.colorSchemeMql?.removeEventListener("change", this.onColorSchemeChange);
    this.colorSchemeMql = null;
    document.removeEventListener("visibilitychange", this.onVisibilityChange);
    this.destroyed = true;
  }

  /**
   * Cached behind `dirty` — a `getComputedStyle` read is a layout read, and
   * doing it every frame instead of once per invalidation is the difference
   * between an idle orb and a jank source. Resolves both the gradient stops
   * and the dark-mode flag together, since both only need to change on the
   * same theme invalidation.
   */
  private resolveStops(): readonly Rgb[] {
    if (this.dirty) {
      this.stops = this.probeStops();
      this.darkMode = this.resolveDarkMode();
      this.dirty = false;
    }
    return this.stops;
  }

  /**
   * Resolves the `bg-cog-ai` design token to its gradient stops via a
   * hidden, zero-impact probe element. jsdom (and any environment that
   * doesn't compute gradient backgrounds) always yields fewer than 2 stops
   * here, so this falls back to today's flat canvas-color behaviour,
   * treated as a one-stop ramp.
   */
  private probeStops(): readonly Rgb[] {
    const probe = document.createElement("div");
    probe.className = "bg-cog-ai";
    probe.style.position = "absolute";
    probe.style.width = "0";
    probe.style.height = "0";
    probe.style.visibility = "hidden";
    probe.style.pointerEvents = "none";
    document.body.appendChild(probe);
    const backgroundImage = getComputedStyle(probe).backgroundImage;
    document.body.removeChild(probe);

    const gradientStops = parseGradientStops(backgroundImage);
    if (gradientStops.length >= 2) {
      return gradientStops;
    }

    const fallback = parseGradientStops(getComputedStyle(this.canvas).color);
    return fallback.length > 0 ? fallback : [{ r: 0, g: 0, b: 0 }];
  }

  /**
   * Dark-mode is read from the same `prefers-color-scheme` media query and
   * `<html>` class/`data-theme` attribute the engine already observes via
   * `installThemeWatchers` — no new listeners, just a read at invalidation
   * time instead of every frame.
   *
   * `data-theme="light"` is checked first and short-circuits the rest:
   * per `styles/index.css`, the dark palette applies as
   * `@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) }`,
   * so an explicit light override beats the OS preference. Skipping this
   * check would use the dark-only ramp window (`RAMP_WINDOW_DARK`) on a
   * light surface for a forced-light page on a dark-OS machine.
   */
  private resolveDarkMode(): boolean {
    const root = document.documentElement;
    if (root.getAttribute("data-theme") === "light") {
      return false;
    }
    if (this.colorSchemeMql?.matches) {
      return true;
    }
    return root.classList.contains("dark") || root.getAttribute("data-theme") === "dark";
  }

  /**
   * Marks the cached colour stale; repaints immediately if the loop isn't
   * running. The loop can be stopped for reasons other than reduced motion
   * — `setPaused(true)`, a hidden tab, or being scrolled off-screen — and
   * `setPaused`'s contract is to hold the last frame, so a theme change
   * while stopped must repaint here or the stale palette would show
   * indefinitely (nothing else will touch the canvas until resumed).
   */
  private invalidate(): void {
    this.dirty = true;
    if (this.reducedMotion || this.raf === null) {
      this.draw(this.frozenT());
    }
  }

  /**
   * The time (seconds) a frame drawn while the loop is stopped should show.
   * When paused mid-loop, reproduces the exact elapsed time the loop was
   * frozen at so an invalidation repaint doesn't jump the animation's pose;
   * otherwise (reduced motion, or never started) falls back to the fixed
   * contemplative static-frame time.
   */
  private frozenT(): number {
    if (this.t0 !== null && this.pausedAt !== null) {
      return (this.pausedAt - this.t0) / 1000;
    }
    return STATIC_FRAME_T;
  }

  private installThemeWatchers(): void {
    this.mutationObserver = new MutationObserver(() => this.invalidate());
    this.mutationObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme"],
    });

    this.colorSchemeMql = window.matchMedia("(prefers-color-scheme: dark)");
    this.colorSchemeMql.addEventListener("change", this.onColorSchemeChange);
  }

  private readonly onVisibilityChange = (): void => {
    this.documentHidden = document.hidden;
    this.sync();
  };

  private readonly onReducedMotionChange = (event: { matches: boolean }): void => {
    this.reducedMotion = event.matches;
    this.invalidate();
    this.sync();
  };

  private readonly onColorSchemeChange = (): void => {
    this.invalidate();
  };
}


