import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { cleanup, render, screen } from "@testing-library/react";
import { ThinkingOrb } from "./ThinkingOrb";

// ── Fake 2D context, matching the shape OrbEngine actually calls. ───────
function makeFakeCtx() {
  const ctx = {
    fillStyle: "",
    globalAlpha: 1,
    clearRect: vi.fn(),
    beginPath: vi.fn(),
    arc: vi.fn(),
    fill: vi.fn(),
    setTransform: vi.fn(),
  };
  return ctx as unknown as CanvasRenderingContext2D;
}

// ── Fake IntersectionObserver, tracking observe/disconnect calls. ───────
function makeIOStub() {
  const observe = vi.fn();
  const disconnect = vi.fn();
  class FakeIntersectionObserver {
    constructor(_cb: IntersectionObserverCallback) {
      // no-op: tests here don't need to drive visibility transitions
    }
    observe(el: Element): void {
      observe(el);
    }
    unobserve(): void {}
    disconnect(): void {
      disconnect();
    }
    takeRecords(): IntersectionObserverEntry[] {
      return [];
    }
  }
  return { FakeIntersectionObserver, observe, disconnect };
}

// ── Fake matchMedia — no legacy addListener/removeListener (jsdom 25 /
// tests/setup.ts stub doesn't have them either; OrbEngine only uses the
// modern EventTarget-style API). ─────────────────────────────────────────
function makeMatchMediaStub() {
  return vi.fn((query: string) => ({
    matches: false,
    media: query,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: () => false,
  }));
}

// Real id -> callback map so cancelAnimationFrame actually removes a
// pending frame, matching browser semantics (a cancelled id never fires).
// A spy that merely records the call without removing from the queue would
// let a stale `loop` closure re-schedule itself forever after destroy().
let rafPending: Map<number, FrameRequestCallback>;
let nextRafId: number;
let rafSpy: ReturnType<typeof vi.spyOn>;
let cafSpy: ReturnType<typeof vi.spyOn>;

function flushRaf(time = 16): void {
  const entries = Array.from(rafPending.entries());
  rafPending.clear();
  for (const [, cb] of entries) cb(time);
}

beforeEach(() => {
  vi.stubGlobal("matchMedia", makeMatchMediaStub());
  const io = makeIOStub();
  vi.stubGlobal("IntersectionObserver", io.FakeIntersectionObserver);

  rafPending = new Map();
  nextRafId = 1;
  rafSpy = vi.spyOn(window, "requestAnimationFrame").mockImplementation((cb) => {
    const id = nextRafId++;
    rafPending.set(id, cb);
    return id;
  });
  cafSpy = vi.spyOn(window, "cancelAnimationFrame").mockImplementation((id: number) => {
    rafPending.delete(id);
  });
});

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe("ThinkingOrb — null ctx regression (jsdom getContext('2d') returns null)", () => {
  it("mounts and unmounts cleanly with a null ctx, no throw", () => {
    // Deliberately NOT stubbing getContext here — real jsdom 25 returns null
    // from canvas.getContext("2d") without throwing. If the effect body ever
    // stops early-returning on that null, this is the test that catches it.
    expect(() => {
      const { unmount } = render(<ThinkingOrb />);
      unmount();
    }).not.toThrow();
  });

  it("still sizes the canvas to the requested slot when the engine never mounts", () => {
    // Uses the global getContext stub (returns null) from tests/setup.ts —
    // no engine is ever constructed, so applySize() never runs. Without an
    // explicit size on the element itself, the canvas keeps jsdom's
    // intrinsic 300x150 default and overflows a fixed-size flex slot
    // (e.g. AiHero's h-cog-8-5 w-cog-8-5). It must degrade to the requested size
    // instead.
    const { container, unmount } = render(<ThinkingOrb size={56} />);
    const canvas = container.querySelector("canvas") as HTMLCanvasElement;
    expect(canvas.style.width).toBe("56px");
    expect(canvas.style.height).toBe("56px");
    expect(canvas.width).toBe(56);
    expect(canvas.height).toBe(56);
    unmount();
  });
});

describe("ThinkingOrb — rendered markup", () => {
  it("renders aria-hidden, no role, and contributes zero role=status nodes", () => {
    const { container, unmount } = render(<ThinkingOrb />);
    const canvas = container.querySelector("canvas");
    expect(canvas).not.toBeNull();
    expect(canvas).toHaveAttribute("aria-hidden", "true");
    expect(canvas?.getAttribute("role")).toBeNull();
    expect(screen.queryAllByRole("status")).toHaveLength(0);
    unmount();
  });

  it("merges className last via cn(), keeping the base text-color classes", () => {
    const { container, unmount } = render(<ThinkingOrb className="my-extra-class" />);
    const canvas = container.querySelector("canvas");
    expect(canvas?.className).toContain("text-cog-blue-600");
    expect(canvas?.className).toContain("dark:text-cog-blue-300");
    expect(canvas?.className).toContain("my-extra-class");
    unmount();
  });
});

describe("ThinkingOrb — lifecycle with a live (non-null) ctx", () => {
  it("calls cancelAnimationFrame on unmount and fires no rAF callback after unmount", () => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(makeFakeCtx());
    const { unmount } = render(<ThinkingOrb />);
    expect(rafSpy).toHaveBeenCalled();
    unmount();
    expect(cafSpy).toHaveBeenCalled();

    const pendingAtUnmount = rafPending.size;
    flushRaf();
    // No new frame should have been scheduled by a callback that fired
    // after the engine was destroyed.
    expect(rafPending.size).toBe(0);
    expect(pendingAtUnmount).toBe(0);
  });

  it("re-rendering with unchanged props does not reallocate the backing store or restart the loop", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { rerender } = render(<ThinkingOrb mode="orbits" size={64} speed={1} paused={false} />);

    const setTransformCallsAfterMount = (ctx.setTransform as ReturnType<typeof vi.fn>).mock
      .calls.length;
    const rafCallsAfterMount = rafSpy.mock.calls.length;

    rerender(<ThinkingOrb mode="orbits" size={64} speed={1} paused={false} />);

    expect((ctx.setTransform as ReturnType<typeof vi.fn>).mock.calls.length).toBe(
      setTransformCallsAfterMount,
    );
    expect(rafSpy.mock.calls.length).toBe(rafCallsAfterMount);
  });

  it("calls IntersectionObserver.observe with the canvas element and disconnects on unmount", () => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(makeFakeCtx());
    const observeSpy = vi.fn();
    const disconnectSpy = vi.fn();
    class TrackedIO {
      constructor(_cb: IntersectionObserverCallback) {}
      observe(el: Element): void {
        observeSpy(el);
      }
      unobserve(): void {}
      disconnect(): void {
        disconnectSpy();
      }
      takeRecords(): IntersectionObserverEntry[] {
        return [];
      }
    }
    vi.stubGlobal("IntersectionObserver", TrackedIO);

    const { container, unmount } = render(<ThinkingOrb />);
    const canvas = container.querySelector("canvas");
    expect(observeSpy).toHaveBeenCalledWith(canvas);

    unmount();
    expect(disconnectSpy).toHaveBeenCalled();
  });
});

describe("ThinkingOrb — defaults and clamping", () => {
  it("defaults to mode='orbits', size=40, speed=1, paused=false and applies them to the engine", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { container } = render(<ThinkingOrb />);
    const canvas = container.querySelector("canvas") as HTMLCanvasElement;
    expect(canvas.style.width).toBe("40px");
    expect(canvas.style.height).toBe("40px");
  });

  it("clamps size below the floor up to 16", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { container } = render(<ThinkingOrb size={2} />);
    const canvas = container.querySelector("canvas") as HTMLCanvasElement;
    expect(canvas.style.width).toBe("16px");
  });

  it("clamps size above the ceiling down to 128", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { container } = render(<ThinkingOrb size={999} />);
    const canvas = container.querySelector("canvas") as HTMLCanvasElement;
    expect(canvas.style.width).toBe("128px");
  });

  it("passes through the AiHero size of 56 unclamped", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { container } = render(<ThinkingOrb size={56} />);
    const canvas = container.querySelector("canvas") as HTMLCanvasElement;
    expect(canvas.style.width).toBe("56px");
  });

  it("paused=true holds the loop stopped: no rAF callback is scheduled after mount", () => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(makeFakeCtx());
    render(<ThinkingOrb paused />);
    // Effect A (mount) starts the loop before effect C (paused) can stop it
