/**
 * ThinkingOrb — thin React shell around `OrbEngine` (see Task 2). Owns only
 * the canvas ref, the null-context guard, and prop wiring; all rendering,
 * sizing, and pause/visibility semantics live in the engine. Split into
 * three effects deliberately: mount/destroy must never re-run on prop
 * churn (that would restart the loop and flash the canvas), so param sync
 * and pause are separate, narrowly-scoped effects.
 */

import { useEffect, useRef } from "react";
import type { HTMLAttributes } from "react";
import { cn } from "@omnicore-platform/ui";
import { OrbEngine } from "./OrbEngine";
import type { ThinkingOrbMode } from "./orbMath";

const DEFAULT_SIZE = 40;
const DEFAULT_SPEED = 1;
const MIN_SIZE = 16;
const MAX_SIZE = 128;
const MIN_SPEED = 0.25;
const MAX_SPEED = 3;

const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value));

export interface ThinkingOrbProps
  extends Omit<HTMLAttributes<HTMLCanvasElement>, "children"> {
  readonly mode?: ThinkingOrbMode;
  readonly size?: number;
  readonly speed?: number;
  readonly paused?: boolean;
  readonly className?: string;
}

export function ThinkingOrb({
  mode = "orbits",
  size = DEFAULT_SIZE,
  speed = DEFAULT_SPEED,
  paused = false,
  className,
  ...rest
}: ThinkingOrbProps): React.JSX.Element {
  const ref = useRef<HTMLCanvasElement>(null);
  const engineRef = useRef<OrbEngine | null>(null);

  const clampedSize = clamp(size, MIN_SIZE, MAX_SIZE);
  const clampedSpeed = clamp(speed, MIN_SPEED, MAX_SPEED);

  useEffect(() => {
    const el = ref.current;
    const ctx = el?.getContext("2d");
    if (!el || !ctx) {
      return;
    }
    const engine = new OrbEngine(el, ctx, {
      mode,
      size: clampedSize,
      speed: clampedSpeed,
    });
    engineRef.current = engine;
    engine.mount();
    return () => {
      engine.destroy();
      engineRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    engineRef.current?.setParams({
      mode,
      size: clampedSize,
      speed: clampedSpeed,
    });
  }, [mode, clampedSize, clampedSpeed]);

  useEffect(() => {
    engineRef.current?.setPaused(paused);
  }, [paused]);

  return (
    <canvas
      ref={ref}
      aria-hidden="true"
      className={cn("text-cog-blue-600 dark:text-cog-blue-300", className)}
      // Explicit width/height/style here — not just via OrbEngine.applySize()
      // — so the canvas is correctly sized from first paint even when
      // getContext("2d") returns null and no engine is ever constructed
      // (privacy extensions, exhausted GPU contexts). Without this the
      // element keeps its intrinsic 300x150 default and overflows any
      // fixed-size slot (e.g. AiHero's h-cog-8-5 w-cog-8-5). OrbEngine.applySize()
      // still owns the DPR-scaled backing store once a context exists.
      width={clampedSize}
      height={clampedSize}
      style={{ width: clampedSize, height: clampedSize }}
      {...rest}
    />
  );
}


