// ── Fake matchMedia: tracks per-query listeners so tests can dispatch
// synthetic "change" events (jsdom's real matchMedia never matches and the
// suite-wide stub in tests/setup.ts has no-op add/removeEventListener). ──
interface FakeMql {
  matches: boolean;
  listeners: Set<(e: { matches: boolean }) => void>;
}
function makeMatchMediaStub() {
  const byQuery = new Map<string, FakeMql>();
  const removeSpies: Array<{ query: string; spy: ReturnType<typeof vi.fn> }> = [];
  const matchMedia = vi.fn((query: string) => {
    let state = byQuery.get(query);
    if (!state) {
      state = { matches: false, listeners: new Set() };
      byQuery.set(query, state);
    }
    const removeEventListener = vi.fn(
      (_type: string, cb: (e: { matches: boolean }) => void) => {
        state!.listeners.delete(cb);
      },
    );
    removeSpies.push({ query, spy: removeEventListener });
    return {
      get matches() {
        return state!.matches;
      },
      media: query,
      addEventListener: vi.fn((_type: string, cb: (e: { matches: boolean }) => void) => {
        state!.listeners.add(cb);
      }),
      removeEventListener,
      dispatchEvent: () => false,
    };
  });
  return {
    matchMedia,
    trigger(query: string, matches: boolean) {
      const state = byQuery.get(query);
      if (!state) return;
      state.matches = matches;
      for (const cb of state.listeners) cb({ matches });
    },
    listenerCount(query: string) {
      return byQuery.get(query)?.listeners.size ?? 0;
    },
    removeCallCount(query: string) {
      return removeSpies
        .filter((r) => r.query === query)
        .reduce((n, r) => n + r.spy.mock.calls.length, 0);
    },
  };
}

// ── Fake IntersectionObserver ────────────────────────────────────────────
function makeIOStub() {
  let callback: IntersectionObserverCallback | null = null;
  const disconnect = vi.fn();
  const observe = vi.fn();
  class FakeIntersectionObserver {
    constructor(cb: IntersectionObserverCallback) {
      callback = cb;
    }
    observe(el: Element): void {
      observe(el);
    }
    unobserve(): void {}
    disconnect(): void {
      disconnect();
    }
    takeRecords(): IntersectionObserverEntry[] {
      return [];
    }
  }
  return {
    FakeIntersectionObserver,
    disconnect,
    observe,
    trigger(isIntersecting: boolean) {
      callback?.(
        [{ isIntersecting } as IntersectionObserverEntry],
        null as unknown as IntersectionObserver,
      );
    },
  };
}

function setHidden(hidden: boolean): void {
  Object.defineProperty(document, "hidden", {
    configurable: true,
