  "linear-gradient(135deg, rgb(26, 79, 214) 0%, rgb(109, 40, 217) 50%, rgb(180, 83, 9) 100%)";

/**
 * Stubs `getComputedStyle` so a probe element carrying the `bg-cog-ai`
