import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { cleanup, render, screen } from "@testing-library/react";
import { ThinkingOrb } from "./ThinkingOrb";

// ── Fake 2D context, matching the shape OrbEngine actually calls. ───────
function makeFakeCtx() {
  const ctx = {
    fillStyle: "",
    globalAlpha: 1,
    clearRect: vi.fn(),
    beginPath: vi.fn(),
    arc: vi.fn(),
    fill: vi.fn(),
    setTransform: vi.fn(),
  };
  return ctx as unknown as CanvasRenderingContext2D;
}

// ── Fake IntersectionObserver, tracking observe/disconnect calls. ───────
function makeIOStub() {
  const observe = vi.fn();
  const disconnect = vi.fn();
  class FakeIntersectionObserver {
    constructor(_cb: IntersectionObserverCallback) {
      // no-op: tests here don't need to drive visibility transitions
    }
    observe(el: Element): void {
      observe(el);
    }
    unobserve(): void {}
    disconnect(): void {
      disconnect();
    }
    takeRecords(): IntersectionObserverEntry[] {
      return [];
    }
  }
  return { FakeIntersectionObserver, observe, disconnect };
}

// ── Fake matchMedia — no legacy addListener/removeListener (jsdom 25 /
// tests/setup.ts stub doesn't have them either; OrbEngine only uses the
// modern EventTarget-style API). ─────────────────────────────────────────
function makeMatchMediaStub() {
  return vi.fn((query: string) => ({
    matches: false,
    media: query,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: () => false,
  }));
}

// Real id -> callback map so cancelAnimationFrame actually removes a
// pending frame, matching browser semantics (a cancelled id never fires).
// A spy that merely records the call without removing from the queue would
// let a stale `loop` closure re-schedule itself forever after destroy().
let rafPending: Map<number, FrameRequestCallback>;
let nextRafId: number;
let rafSpy: ReturnType<typeof vi.spyOn>;
let cafSpy: ReturnType<typeof vi.spyOn>;

function flushRaf(time = 16): void {
  const entries = Array.from(rafPending.entries());
  rafPending.clear();
  for (const [, cb] of entries) cb(time);
}

beforeEach(() => {
  vi.stubGlobal("matchMedia", makeMatchMediaStub());
  const io = makeIOStub();
  vi.stubGlobal("IntersectionObserver", io.FakeIntersectionObserver);

  rafPending = new Map();
  nextRafId = 1;
  rafSpy = vi.spyOn(window, "requestAnimationFrame").mockImplementation((cb) => {
    const id = nextRafId++;
    rafPending.set(id, cb);
    return id;
  });
  cafSpy = vi.spyOn(window, "cancelAnimationFrame").mockImplementation((id: number) => {
    rafPending.delete(id);
  });
});

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe("ThinkingOrb — null ctx regression (jsdom getContext('2d') returns null)", () => {
  it("mounts and unmounts cleanly with a null ctx, no throw", () => {
    // Deliberately NOT stubbing getContext here — real jsdom 25 returns null
    // from canvas.getContext("2d") without throwing. If the effect body ever
