describe("ThinkingOrb — lifecycle with a live (non-null) ctx", () => {
  it("calls cancelAnimationFrame on unmount and fires no rAF callback after unmount", () => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(makeFakeCtx());
    const { unmount } = render(<ThinkingOrb />);
    expect(rafSpy).toHaveBeenCalled();
    unmount();
    expect(cafSpy).toHaveBeenCalled();

    const pendingAtUnmount = rafPending.size;
    flushRaf();
    // No new frame should have been scheduled by a callback that fired
    // after the engine was destroyed.
    expect(rafPending.size).toBe(0);
    expect(pendingAtUnmount).toBe(0);
  });

  it("re-rendering with unchanged props does not reallocate the backing store or restart the loop", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { rerender } = render(<ThinkingOrb mode="orbits" size={64} speed={1} paused={false} />);

    const setTransformCallsAfterMount = (ctx.setTransform as ReturnType<typeof vi.fn>).mock
      .calls.length;
    const rafCallsAfterMount = rafSpy.mock.calls.length;

    rerender(<ThinkingOrb mode="orbits" size={64} speed={1} paused={false} />);

    expect((ctx.setTransform as ReturnType<typeof vi.fn>).mock.calls.length).toBe(
      setTransformCallsAfterMount,
    );
    expect(rafSpy.mock.calls.length).toBe(rafCallsAfterMount);
  });

  it("calls IntersectionObserver.observe with the canvas element and disconnects on unmount", () => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(makeFakeCtx());
    const observeSpy = vi.fn();
    const disconnectSpy = vi.fn();
    class TrackedIO {
      constructor(_cb: IntersectionObserverCallback) {}
      observe(el: Element): void {
        observeSpy(el);
