    const { container, unmount } = render(<ThinkingOrb />);
    const canvas = container.querySelector("canvas");
    expect(observeSpy).toHaveBeenCalledWith(canvas);

    unmount();
    expect(disconnectSpy).toHaveBeenCalled();
  });
});

describe("ThinkingOrb — defaults and clamping", () => {
  it("defaults to mode='orbits', size=40, speed=1, paused=false and applies them to the engine", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { container } = render(<ThinkingOrb />);
    const canvas = container.querySelector("canvas") as HTMLCanvasElement;
    expect(canvas.style.width).toBe("40px");
    expect(canvas.style.height).toBe("40px");
  });

  it("clamps size below the floor up to 16", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { container } = render(<ThinkingOrb size={2} />);
    const canvas = container.querySelector("canvas") as HTMLCanvasElement;
    expect(canvas.style.width).toBe("16px");
  });

  it("clamps size above the ceiling down to 128", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { container } = render(<ThinkingOrb size={999} />);
    const canvas = container.querySelector("canvas") as HTMLCanvasElement;
    expect(canvas.style.width).toBe("128px");
  });

  it("passes through the AiHero size of 56 unclamped", () => {
    const ctx = makeFakeCtx();
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(ctx);
    const { container } = render(<ThinkingOrb size={56} />);
