import { describe, expect, it } from "vitest";
import {
  densityFor,
  fibonacciSphere,
  frameParticles,
  parseGradientStops,
  prefersReducedMotion,
  rampPosition,
  resolveDpr,
  sampleRamp,
  shouldRunLoop,
} from "./orbMath";

describe("fibonacciSphere", () => {
  it("returns exactly n points", () => {
    expect(fibonacciSphere(24)).toHaveLength(24);
  });

  it("returns unit-length points within float tolerance", () => {
    const pts = fibonacciSphere(30);
    for (const p of pts) {
      const len = Math.sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
      expect(len).toBeCloseTo(1, 5);
    }
