/**
 * Pure motion math for the wizard's "thinking orb" ambient loader (see
 * Task 1 of the Thinking Orb plan). Deliberately has NO DOM dependency —
 * every function here is a plain, deterministic transform of numeric
 * inputs so it can be unit tested without a canvas or a browser, and so
 * the rendering engine (a later task) can stay a thin adapter that just
 * calls these functions once per frame and draws whatever comes back.
 */

export type ThinkingOrbMode = "orbits" | "scan";

export interface Vec3 {
  readonly x: number;
  readonly y: number;
  readonly z: number;
}

export interface OrbParticle {
  readonly x: number;
  readonly y: number;
  readonly r: number;
  readonly a: number;
  /** Normalized depth in [0, 1] — the same depth term alpha/radius already derive from. */
  readonly d: number;
}

const GOLDEN = 2.399963229728653;

const clamp01 = (v: number): number => Math.min(1, Math.max(0, v));

// Memoized by n: the same lattice is recomputed every frame otherwise, and
// the point set for a given n never changes.
const sphereCache = new Map<number, readonly Vec3[]>();

/**
 * Deterministic Fibonacci-lattice points on the unit sphere. Memoized by
 * `n` at module scope — repeat calls with the same `n` return the exact
 * same array reference.
 */
export function fibonacciSphere(n: number): readonly Vec3[] {
  const cached = sphereCache.get(n);
  if (cached) {
    return cached;
  }

  const points: Vec3[] = [];
  for (let i = 0; i < n; i++) {
    const y = 1 - (2 * i + 1) / n;
    const radius = Math.sqrt(Math.max(0, 1 - y * y));
    const theta = GOLDEN * i;
    const x = Math.cos(theta) * radius;
    const z = Math.sin(theta) * radius;
    points.push({ x, y, z });
  }

  const frozen: readonly Vec3[] = Object.freeze(points);
  sphereCache.set(n, frozen);
  return frozen;
}

/**
 * Particle-density factor for a given orb size in px, clamped to
 * [0.55, 1] — smaller orbs render fewer particles than the reference
 * 160px size, larger orbs render the full count.
 */
export function densityFor(size: number): number {
  return Math.min(1, Math.max(0.55, size / 160));
}

/** Shared geometry both modes derive from a given orb size. */
interface OrbGeometry {
  readonly density: number;
  readonly R: number;
  readonly dot: number;
  readonly centre: number;
}

function orbGeometry(size: number): OrbGeometry {
  return {
    density: densityFor(size),
    R: size * 0.38,
    dot: Math.max(0.9, size * 0.045),
    centre: size / 2,
  };
}

// Depth drives radius and alpha identically in both modes; `x`/`y` are the
// pre-centre offsets from the orb's origin.
function shade(g: OrbGeometry, x: number, y: number, d: number): OrbParticle {
  return {
    x: x + g.centre,
    y: y + g.centre,
    r: g.dot * (0.55 + 0.45 * d),
    a: clamp01(0.3 + 0.7 * d),
    d,
  };
}

interface OrbitRing {
  readonly tilt: number;
  readonly ry: number;
  readonly dir: 1 | -1;
  readonly n: number;
}

const ORBIT_RINGS: readonly OrbitRing[] = [
  { tilt: -0.45, ry: 0.34, dir: 1, n: 7 },
  { tilt: 0.62, ry: 0.26, dir: -1, n: 6 },
  { tilt: 1.65, ry: 0.44, dir: 1, n: 5 },
];

function frameOrbits(
  t: number,
  size: number,
  speed: number,
): readonly OrbParticle[] {
  const g = orbGeometry(size);
  const w = 2.1 * speed;

  const particles: OrbParticle[] = [];
  for (const ring of ORBIT_RINGS) {
    const n = Math.max(3, Math.round(ring.n * g.density));
    const cosTilt = Math.cos(ring.tilt);
    const sinTilt = Math.sin(ring.tilt);

    for (let i = 0; i < n; i++) {
      const a = ring.dir * w * t + (i / n) * 2 * Math.PI;
      const lx = Math.cos(a) * g.R;
      const ly = Math.sin(a) * g.R * ring.ry;
      const rx = lx * cosTilt - ly * sinTilt;
      const ry = lx * sinTilt + ly * cosTilt;

      const depth = (Math.sin(a) + 1) / 2;

      particles.push(shade(g, rx, ry, depth));
    }
  }

  return particles;
}

function frameScan(
  t: number,
  size: number,
  speed: number,
): readonly OrbParticle[] {
  const g = orbGeometry(size);
  const n = Math.max(12, Math.round(30 * g.density));
  const points = fibonacciSphere(n);

  const rot = 1.35 * speed * t;
  const cosRot = Math.cos(rot);
  const sinRot = Math.sin(rot);

  const bandY = Math.sin(t * 0.9) * g.R;
  const bandW = g.R * 0.42;

  const particles: OrbParticle[] = [];
  for (const p of points) {
    // Rotate about the Y axis.
    const rx = p.x * cosRot + p.z * sinRot;
    const rz = -p.x * sinRot + p.z * cosRot;

    const px = rx * g.R;
    const py = p.y * g.R;

    const near = Math.max(0, 1 - Math.abs(py - bandY) / bandW);
    const depth = (rz + 1) / 2;
    const boostedDepth = Math.min(1, depth + near);

    particles.push(shade(g, px, py, boostedDepth));
  }

  return particles;
}

/**
 * Computes the orb's particle field for a single frame. Pure function of
 * (mode, t, size, speed) — same inputs always produce the same output, so
 * the caller (the render loop) owns all mutable state.
 */
export function frameParticles(
  mode: ThinkingOrbMode,
  t: number,
  size: number,
  speed: number,
): readonly OrbParticle[] {
  return mode === "scan"
    ? frameScan(t, size, speed)
    : frameOrbits(t, size, speed);
}

export interface Rgb {
  readonly r: number;
  readonly g: number;
  readonly b: number;
}

// Matches `rgb(r, g, b)` / `rgba(r, g, b, a)` stop colors inside a computed
// `background-image` gradient string, tolerating arbitrary whitespace. The
// alpha channel (if present) is captured but intentionally discarded — the
// orb's ramp is always drawn fully opaque, with translucency handled
// per-particle via `globalAlpha` instead.
const RGB_STOP_RE =
  /rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*(?:,\s*[\d.]+\s*)?\)/g;

/**
 * Extracts color stops, in order, from a computed `background-image`
 * gradient string (e.g. what `getComputedStyle(el).backgroundImage` returns
 * for an element with the `bg-cog-ai` class). Stop *positions* (the `0%`,
 * `50%`, `100%` in the source string) are intentionally ignored — the
 * design token's stops are evenly spaced, so callers can treat the returned
 * array as an evenly-spaced ramp. Returns `[]` for `"none"`, `""`, or any
 * string with no recognizable `rgb()`/`rgba()` stops — this is how jsdom's
 * `getComputedStyle` reports an unresolved gradient, and it's a normal,
 * expected input here (see `OrbEngine`'s solid-color fallback).
 */
export function parseGradientStops(css: string): readonly Rgb[] {
  if (!css) {
    return [];
  }
  const stops: Rgb[] = [];
  for (const match of css.matchAll(RGB_STOP_RE)) {
    stops.push({
      r: Math.round(Number(match[1])),
      g: Math.round(Number(match[2])),
      b: Math.round(Number(match[3])),
    });
  }
  return stops;
}

/**
 * Linearly interpolates a color at position `t` (clamped to [0, 1]) along
 * an evenly-spaced ramp of stops, rounding each channel to an integer.
 *
 * Contract for degenerate inputs: an empty `stops` array has no color to
 * return, so it falls back to black (`{r:0,g:0,b:0}`) rather than throwing
 * — callers that always resolve at least a one-stop fallback (as
 * `OrbEngine` does) never hit this branch in practice; it exists purely as
 * a safe default. A single-stop array returns that stop for every `t`.
 */
export function sampleRamp(stops: readonly Rgb[], t: number): Rgb {
  if (stops.length === 0) {
    return { r: 0, g: 0, b: 0 };
  }
  if (stops.length === 1) {
    return stops[0];
  }
  const clamped = clamp01(t);
  const scaled = clamped * (stops.length - 1);
  const i = Math.min(stops.length - 2, Math.floor(scaled));
  const localT = scaled - i;
  const a = stops[i];
  const b = stops[i + 1];
  return {
    r: Math.round(a.r + (b.r - a.r) * localT),
    g: Math.round(a.g + (b.g - a.g) * localT),
    b: Math.round(a.b + (b.b - a.b) * localT),
  };
}

/** A sub-range of the color ramp that particle depths are mapped onto. */
export interface RampWindow {
  readonly from: number;
  readonly to: number;
}

/**
 * Maps a normalized particle depth `d` (clamped to [0, 1]) onto a
 * sub-range `[ramp.from, ramp.to]` of the color ramp. This exists so a
 * caller can keep the far (or near) end of a gradient as a subtle accent
 * rather than letting every particle reach the ramp's pure endpoint color.
 */
export function rampPosition(d: number, ramp: RampWindow): number {
  const clamped = clamp01(d);
  return ramp.from + clamped * (ramp.to - ramp.from);
}

/**
 * Clamps `window.devicePixelRatio` into a sane render range. Takes the
 * window as a parameter — jsdom always reports devicePixelRatio 1, so the
 * clamping behavior would otherwise be untestable.
 */
export function resolveDpr(win: { devicePixelRatio?: number }): number {
  if (win.devicePixelRatio === undefined) {
    return 1;
  }
  return Math.min(2, Math.max(1, win.devicePixelRatio));
}

/**
 * Reads the `prefers-reduced-motion` media feature. Takes the window as a
 * parameter for the same testability reason as {@link resolveDpr}.
 */
export function prefersReducedMotion(win: {
  matchMedia?: (query: string) => { matches: boolean };
}): boolean {
  if (!win.matchMedia) {
    return false;
  }
  return win.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/**
 * Single source of truth for whether the render loop should keep
 * scheduling frames — exists so the rendering engine never has to inline
 * this `&&` chain itself. The canvas context is not part of the decision:
 * the engine is only ever constructed with a non-null context.
 */
export function shouldRunLoop(s: {
  visible: boolean;
  documentHidden: boolean;
  reducedMotion: boolean;
}): boolean {
  return s.visible && !s.documentHidden && !s.reducedMotion;
}



